","datasets/Hydrangea/fix_repo/h2oai__h2ogpt-3/tests/test.py":"import ast
from pathlib import Path
import types

import pytest


ROOT = Path.cwd()
SOURCE = ROOT / "src/create_data.py"


class OutOfMemoryError(Exception):
    pass


class FakeColumn:
    def __init__(self, values):
        self.values = values

    def replace(self, old, new):
        return FakeColumn([value.replace(old, new) for value in self.values])


class FakeILoc:
    def __init__(self, frame):
        self.frame = frame

    def __getitem__(self, key):
        rows, _ = key
        return FakeFrame(self.frame.rows[rows])


class FakeFrame:
    def __init__(self, rows):
        self.rows = list(rows)
        self.columns = {}
        self.iloc = FakeILoc(self)
        self.shape = (len(self.rows), 2)

    def __getitem__(self, key):
        if isinstance(key, list):
            return self
        if key in self.columns:
            return self.columns[key]
        return FakeColumn([row[key] for row in self.rows])

    def __setitem__(self, key, value):
        self.columns[key] = value


class FakePipe:
    def __init__(self, failures):
        self.failures = failures
        self.batch_sizes = []

    def __call__(self, dataset, batch_size):
        self.batch_sizes.append(batch_size)
        if self.failures:
            self.failures -= 1
            raise OutOfMemoryError("simulated GPU allocation failure")
        return [{"score": 0.5} for _ in dataset.rows]


def load_add_deberta_grade(pipe, empty_cache_calls):
    tree = ast.parse(SOURCE.read_text(encoding="utf-8"))
    function = next(
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef) and node.name == "add_deberta_grade"
    )
    module = ast.Module(body=[function], type_ignores=[])

    class FakeModel:
        def to(self, device):
            return self

    fake_torch = types.SimpleNamespace(
        cuda=types.SimpleNamespace(
            is_available=lambda: True,
            OutOfMemoryError=OutOfMemoryError,
            empty_cache=lambda: empty_cache_calls.append(True),
        )
    )
    fake_transformers = types.SimpleNamespace(
        AutoModelForSequenceClassification=types.SimpleNamespace(
            from_pretrained=lambda name: FakeModel()
        ),
        AutoTokenizer=types.SimpleNamespace(from_pretrained=lambda name: object()),
        pipeline=lambda *args, **kwargs: pipe,
    )
    fake_datasets = types.SimpleNamespace(
        Dataset=types.SimpleNamespace(from_pandas=lambda frame: frame)
    )
    fake_pipeline_utils = types.SimpleNamespace(
        KeyPairDataset=lambda dataset, question, answer: dataset
    )
    fake_tqdm = types.SimpleNamespace(tqdm=lambda values: values)
    fake_psutil = types.SimpleNamespace(cpu_count=lambda logical=False: 1)
    modules = {
        "torch": fake_torch,
        "transformers": fake_transformers,
        "datasets": fake_datasets,
        "transformers.pipelines.pt_utils": fake_pipeline_utils,
        "tqdm": fake_tqdm,
        "psutil": fake_psutil,
    }
    original_import = __import__

    def fake_import(name, globals=None, locals=None, fromlist=(), level=0):
        if name in modules:
            return modules[name]
        return original_import(name, globals, locals, fromlist, level)

    namespace = {
        "os": types.SimpleNamespace(path=types.SimpleNamespace(exists=lambda path: False)),
        "parallel_apply": lambda column, function, n_jobs: FakeColumn(
            [function(value) for value in column.values]
        ),
        "__builtins__": dict(vars(__import__("builtins")), __import__=fake_import),
    }
    exec(compile(module, str(SOURCE), "exec"), namespace)
    return namespace["add_deberta_grade"]


def make_frame():
    return FakeFrame(
        [
            {"text": "<human>: question<bot>: answer", "prompt_type": "human_bot"},
            {"text": "<human>: another<bot>: response", "prompt_type": "human_bot"},
        ]
    )


def test_oom_retry_releases_failed_gpu_allocations():
    empty_cache_calls = []
    pipe = FakePipe(failures=1)
    add_grade = load_add_deberta_grade(pipe, empty_cache_calls)

    frame = add_grade(make_frame())

    assert pipe.batch_sizes == [16, 8]
    assert empty_cache_calls == [True]
    assert frame.columns["grade_deberta"] == [0.5, 0.5]


def test_oom_at_minimum_batch_raises_instead_of_retrying_forever():
    empty_cache_calls = []
    pipe = FakePipe(failures=20)
    add_grade = load_add_deberta_grade(pipe, empty_cache_calls)

    with pytest.raises(OutOfMemoryError):
        add_grade(make_frame())

    assert pipe.batch_sizes == [16, 8, 4, 2, 1]
    assert len(empty_cache_calls) == 4
","scripts/reproduce/reproduce_Hydrangea_h2oai__h2ogpt-3.py":"import argparse
import json
import os
import re
import shutil
import subprocess
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
INSTANCE_ID = "h2oai__h2ogpt-3"
BASE_COMMIT = "15f3a2d564541020f78cfc83bc90722dcda8a960"
ENVIRONMENT = ROOT / "datasets/Hydrangea/environments/h2oai__h2ogpt-15f3a2d5"
ORIGINAL_REPO = ROOT / "datasets/Hydrangea/repo" / INSTANCE_ID
PATCHED_REPO = Path("/tmp") / f"lidl-{INSTANCE_ID}-patched"
ARTIFACTS = ROOT / "datasets/Hydrangea/fix_repo" / INSTANCE_ID
DEFECTS = ROOT / "datasets/Hydrangea/hydrangea_defect.json"
PYTHON = ENVIRONMENT / ".venv/bin/python"
SECRET_MARKERS = ("api_key", "auth", "credential", "password", "secret", "token")
SECRET_PATTERNS = (
    re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----"),
    re.compile(r"\bsk-[A-Za-z0-9_-]{20,}\b"),
    re.compile(r"\bAIza[A-Za-z0-9_-]{20,}\b"),
    re.compile(r"\bya29\.[A-Za-z0-9_-]{20,}\b"),
)


def redact_value(value: str) -> str:
    return "<redacted>" if any(pattern.search(value) for pattern in SECRET_PATTERNS) else value


def safe_environment() -> dict[str, str]:
    return {
        key: "<redacted>" if any(marker in key.lower() for marker in SECRET_MARKERS) else redact_value(value)
        for key, value in os.environ.items()
    }


def run(command: list[str], cwd: Path, phase: str) -> subprocess.CompletedProcess:
    started_at = datetime.now(timezone.utc)
    result = subprocess.run(command, cwd=cwd, text=True, capture_output=True, check=False)
    with (ARTIFACTS / "run.log").open("a", encoding="utf-8") as file:
        file.write(
            f"\n{'=' * 80}\nphase: {phase}\nstarted_at: {started_at.isoformat()}\n"
            f"finished_at: {datetime.now(timezone.utc).isoformat()}\ncwd: {cwd}\n"
            f"command: {subprocess.list2cmdline(command)}\nreturncode: {result.returncode}\n"
            f"stdout:\n{result.stdout}stderr:\n{result.stderr}"
        )
    return result


def append_record(phase: str, stdout: str, returncode: int = 0) -> None:
    now = datetime.now(timezone.utc).isoformat()
    with (ARTIFACTS / "run.log").open("a", encoding="utf-8") as file:
        file.write(
            f"\n{'=' * 80}\nphase: {phase}\nstarted_at: {now}\nfinished_at: {now}\n"
            f"cwd: {ORIGINAL_REPO}\ncommand: manual complete-record and production-path inspection\n"
            f"returncode: {returncode}\nstdout:\n{stdout}stderr:\n"
        )


def complete_record() -> dict:
    return next(
        record
        for record in json.loads(DEFECTS.read_text(encoding="utf-8"))
        if record["instance_id"] == INSTANCE_ID
    )


def record_investigation() -> None:
    environment = "\n".join(f"{key}={value}" for key, value in sorted(safe_environment().items()))
    append_record(
        "gpu-oom-retry-production-contract-investigation",
        f"""instance_id: {INSTANCE_ID}
base_commit: {BASE_COMMIT}
complete_record:
{json.dumps(complete_record(), ensure_ascii=False, indent=2)}
defect_alignment:
- The defect title identifies a CUDA illegal-memory failure; the generic app.py/query steps are inaccurate because the labeled production path performs GPU reward-model grading during data preparation.
actual_production_path:
- add_deberta_grade batches dataframe rows through a CUDA transformers pipeline and attempts to recover from torch.cuda.OutOfMemoryError by halving micro_batch.
root_cause:
- The OOM handler leaves end advanced, so the while condition can terminate without retrying failed rows; it also retains failed CUDA allocations and retries forever once micro_batch is already one.
patch:
- Reset end to start, release cached CUDA allocations before retry, and re-raise an unrecoverable OOM at minimum batch size.
behavioral_verification:
- The tests execute the exact production function through AST isolation, inject deterministic CUDA OOMs, prove a 16-to-8 retry succeeds without losing rows, and prove persistent failure terminates at batch size one.
environment:
{environment}
""",
    )


def require(result: subprocess.CompletedProcess, expected: int, phase: str) -> None:
    if result.returncode != expected:
        raise SystemExit(f"{phase} returned {result.returncode}, expected {expected}")


def prepare_workspace() -> None:
    if PATCHED_REPO.exists():
        shutil.rmtree(PATCHED_REPO)
    shutil.copytree(ORIGINAL_REPO, PATCHED_REPO, symlinks=True)
    require(
        run(["patch", "--batch", "-p1", "-i", str(ARTIFACTS / "patch.diff")], PATCHED_REPO, "apply-patch-isolated-workspace"),
        0,
        "apply-patch-isolated-workspace",
    )


def run_local() -> None:
    tests = str(ARTIFACTS / "tests/test.py")
    require(run([str(PYTHON), "-m", "pytest", "-q", tests], ORIGINAL_REPO, "original-gpu-oom-retry-fail-to-pass"), 1, "original-gpu-oom-retry-fail-to-pass")
    require(run(["patch", "--dry-run", "--batch", "-p1", "-i", str(ARTIFACTS / "patch.diff")], ORIGINAL_REPO, "immutable-source-patch-dry-run"), 0, "immutable-source-patch-dry-run")
    prepare_workspace()
    require(run([str(PYTHON), "-m", "pytest", "-q", tests], PATCHED_REPO, "patched-workspace-gpu-oom-retry"), 0, "patched-workspace-gpu-oom-retry")


def run_docker() -> None:
    for apply_patch, expected in (("0", 1), ("1", 0)):
        tag = f"lidl-{INSTANCE_ID.lower()}-{apply_patch}"
        require(run(["docker", "build", "--build-arg", f"APPLY_PATCH={apply_patch}", "-t", tag, "-f", str(ARTIFACTS / "Dockerfile"), str(ROOT)], ROOT, f"docker-build-apply-patch-{apply_patch}"), 0, f"docker-build-apply-patch-{apply_patch}")
        require(run(["docker", "run", "--rm", tag], ROOT, f"docker-run-apply-patch-{apply_patch}"), expected, f"docker-run-apply-patch-{apply_patch}")


def validate_artifacts() -> None:
    python_files = [ARTIFACTS / "tests/test.py", Path(__file__), ORIGINAL_REPO / "src/create_data.py"]
    for path in python_files:
        require(run([str(PYTHON), "-m", "py_compile", str(path)], ROOT, f"compile-{path.name}"), 0, f"compile-{path.name}")
    scanned = [ARTIFACTS / "tests/test.py", ARTIFACTS / "Dockerfile", ARTIFACTS / "patch.diff", ARTIFACTS / "run.log", Path(__file__)]
    hits = [f"{path}: {pattern.pattern}" for path in scanned for pattern in SECRET_PATTERNS if pattern.search(path.read_text(encoding="utf-8"))]
    append_record(
        "compile-and-secret-scan",
        f"compiled_python_files={len(python_files)}\nscanned_files={len(scanned)}\nsecret_hits={len(hits)}\npatch_bytes={(ARTIFACTS / 'patch.diff').stat().st_size}\n" + ("\n".join(hits) + "\n" if hits else ""),
        1 if hits else 0,
    )
    if hits:
        raise SystemExit("Secret scan found credentials")


def main() -> None:
    parser = argparse.ArgumentParser(description=f"Reproduce {INSTANCE_ID}.")
    parser.add_argument("--runtime", choices=["local", "docker", "all"], default="local")
    args = parser.parse_args()
    ARTIFACTS.mkdir(parents=True, exist_ok=True)
    (ARTIFACTS / "run.log").write_text("", encoding="utf-8")
    record_investigation()
    if args.runtime in ("local", "all"):
        run_local()
    if args.runtime in ("docker", "all"):
        run_docker()
    validate_artifacts()


if __name__ == "__main__":
    main()
