","datasets/Hydrangea/fix_repo/vmayoral__PentestGPT-2/tests/test.py":"import ast
from pathlib import Path

import pytest


ROOT = Path.cwd()
API_PATHS = (
    ROOT / "utils" / "chatgpt_api.py",
    ROOT / "pentestgpt" / "utils" / "chatgpt_api.py",
)


def api_class(path: Path) -> ast.ClassDef:
    tree = ast.parse(path.read_text(encoding="utf-8"))
    return next(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == "ChatGPTAPI"
    )


def method_node(path: Path, name: str) -> ast.FunctionDef:
    return next(
        node
        for node in api_class(path).body
        if isinstance(node, ast.FunctionDef) and node.name == name
    )


def method_source(path: Path, name: str) -> str:
    return ast.unparse(method_node(path, name))


def history_method(path: Path):
    function = method_node(path, "get_conversation_history")
    module = ast.Module(body=[function], type_ignores=[])
    ast.fix_missing_locations(module)
    namespace = {}
    exec(compile(module, str(path), "exec"), namespace)
    return namespace["get_conversation_history"]


@pytest.mark.parametrize("path", API_PATHS)
def test_api_history_returns_all_conversations(path: Path) -> None:
    class StoredConversation:
        def __init__(self, messages):
            self.message_list = messages

    first = [object(), object()]
    second = [object()]
    api = type(
        "FakeAPI",
        (),
        {
            "conversation_dict": {
                "first": StoredConversation(first),
                "second": StoredConversation(second),
            }
        },
    )()
    history = history_method(path)(api)
    assert history == {"first": first, "second": second}


@pytest.mark.parametrize("path", API_PATHS)
def test_api_history_returns_snapshot_lists(path: Path) -> None:
    stored = [object()]
    conversation = type("StoredConversation", (), {"message_list": stored})()
    api = type("FakeAPI", (), {"conversation_dict": {"session": conversation}})()
    history = history_method(path)(api)
    assert history["session"] == stored
    assert history["session"] is not stored


@pytest.mark.parametrize("path", API_PATHS)
def test_empty_api_history_returns_empty_mapping(path: Path) -> None:
    api = type("FakeAPI", (), {"conversation_dict": {}})()
    assert history_method(path)(api) == {}


@pytest.mark.parametrize("path", API_PATHS)
def test_api_message_paths_feed_the_history_store(path: Path) -> None:
    new_message = method_source(path, "send_new_message")
    follow_up = method_source(path, "send_message")
    assert "conversation.message_list.append(message)" in new_message
    assert "self.conversation_dict[conversation_id] = conversation" in new_message
    assert "conversation.message_list.append(message)" in follow_up
    assert "self.conversation_dict[conversation_id] = conversation" in follow_up


@pytest.mark.parametrize("path", API_PATHS)
def test_new_message_return_contract_is_preserved(path: Path) -> None:
    source = method_source(path, "send_new_message")
    assert "return (response, conversation_id)" in source


@pytest.mark.parametrize("path", API_PATHS)
def test_followup_still_replays_recent_history(path: Path) -> None:
    source = method_source(path, "send_message")
    assert "conversation.message_list[-self.history_length:]" in source
    assert "self.chatgpt_completion(chat_message)" in source
