def record_investigation() -> None:
    environment = "\n".join(f"{key}={value}" for key, value in sorted(safe_environment().items()))
    with (ARTIFACTS / "run.log").open("a", encoding="utf-8") as file:
        file.write(
            f"\n{'=' * 80}\nphase: final-api-history-accessor-repair\n"
            f"started_at: {datetime.now(timezone.utc).isoformat()}\nfinished_at: {datetime.now(timezone.utc).isoformat()}\n"
            f"cwd: {ROOT}\nreturncode: 0\ninstance_id: {INSTANCE_ID}\nbase_commit: {BASE_COMMIT}\nstatus: reproducible_fixed\n"
            "production_path:\n- main.py --useAPI and the installed pentestgpt entry point each construct ChatGPTAPI, whose send methods append every exchange to conversation_dict.\n"
            "root_cause:\n- Both source layouts expose get_conversation_history(), but the method is an unfinished bare return and discards the API adapter's populated in-memory history.\n"
            "repair_contract:\n- Return every conversation ID and a snapshot list of its Message objects without network access, changing retention, or adding a persistence system.\n"
            "semantic_invariant:\n- send_new_message and send_message remain the only writers, and callers cannot mutate the stored message list by appending to a returned list.\n"
            "validation_oracle:\n- Six production-contract checks cover both executable source layouts; four fail on immutable source and all six pass in the isolated workspace.\n"
            f"environment:\n{environment}\n"
